const HTML = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>SH01 / Operations</title><style>\n:root{color-scheme:dark;font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;background:#0c1117;color:#e9eef4}*{box-sizing:border-box}body{margin:0}button,input,select{font:inherit}a{color:#84d9b9}a:hover{text-decoration:underline}.shell{max-width:1450px;margin:auto;padding:28px 36px 90px}.top{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;border-bottom:1px solid #344150;padding-bottom:28px}.eyebrow{text-transform:uppercase;letter-spacing:.18em;font-size:11px;color:#81d5b7;font-weight:700}.title{font-size:clamp(32px,5vw,60px);letter-spacing:-.06em;line-height:1.03;margin:10px 0}p{color:#a4b3c0}.meta{font-size:12px;color:#91a6b2}.card{background:#141d27;border:1px solid #2c3c4b;border-radius:14px;padding:22px;margin-top:24px;box-shadow:0 10px 30px #0002}.nav{display:flex;gap:8px;margin:28px 0}.nav button,.btn{color:#dae6e7;background:#1d2a34;border:1px solid #415364;border-radius:9px;padding:10px 15px;cursor:pointer}.nav button[aria-selected=true],.btn:hover{background:#245c50;border-color:#67c5a5;color:#fff}.control{display:flex;flex-wrap:wrap;align-items:end;gap:12px}.control label{font-size:12px;letter-spacing:.03em;color:#afc1c9}.control input,.control select,.secret{display:block;min-width:170px;background:#0e1720;color:#edf4f1;border:1px solid #465666;border-radius:8px;padding:10px;margin-top:5px}.control input[type=date]{min-width:145px}.search{flex:1;min-width:240px!important}table{border-collapse:collapse;width:100%;margin-top:20px}th{text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:#94abb9}td,th{border-bottom:1px solid #283744;padding:13px 11px;vertical-align:top}td{word-break:break-word}tbody tr:hover{background:#1b2933}.scroll{overflow:auto}.badge{display:inline-block;border-radius:100px;padding:3px 9px;font-size:12px;font-weight:700}.green{color:#85e6bd;background:#1a4439}.amber{color:#f8cd81;background:#563d1f}.red{color:#ff9c99;background:#4c2729}.muted{color:#bcc5cd;background:#34414c}.sub{font-size:12px;color:#97a9b7}.error{white-space:pre-wrap;max-width:660px}.empty{padding:28px;color:#9caeb9}.stats{display:flex;gap:10px;flex-wrap:wrap}.stats span{padding:9px 14px;border:1px solid #344b55;border-radius:10px;background:#122027}.secret-panel{max-width:520px}.secret{width:100%}.hidden{display:none!important}#notice{min-height:20px;color:#ffbcbc}@media(max-width:700px){.shell{padding:20px 15px}.top{display:block}.card{padding:15px}td,th{padding:10px 7px;min-width:105px}}\n\n:root{--bg:#0b1118;--panel:#131e29;--ink:#e9eef4;--muted:#a4b3c0;--line:#344150;--field:#0e1720;--accent:#84d9b9}\nhtml[data-theme=light]{color-scheme:light;--bg:#f3f6f8;--panel:#ffffff;--ink:#172b3c;--muted:#516778;--line:#cbd7e0;--field:#f5f8fa;--accent:#126c52}\nbody{background:var(--bg);color:var(--ink)}.card{background:var(--panel);border-color:var(--line)}p,.meta,.sub,.control label,th,.empty{color:var(--muted)}a{color:var(--accent)}.control input,.control select,.secret,.nav button,.btn{background:var(--field);color:var(--ink);border-color:var(--line)}.top,td,th{border-color:var(--line)}\nbutton:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:4px}\nbutton:disabled{opacity:.5;cursor:wait}.scroll{border:1px solid var(--line);border-radius:10px;max-height:65vh}table{margin-top:0}th{position:sticky;top:0;z-index:1;background:var(--panel)}td{max-width:450px}.error{white-space:pre-wrap;max-height:170px;overflow:auto}\n.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.stats span{border-color:var(--line);background:var(--field);padding:16px}.stats strong{display:block;font-size:26px;color:var(--ink)}\n.tags{display:flex;gap:5px;flex-wrap:wrap;margin:6px 0}.tag{font-size:11px;padding:2px 7px;border:1px solid var(--line);border-radius:5px;color:var(--muted)}.legend{font-size:12px;color:var(--muted);margin:12px 0}.bar{height:5px;border-radius:8px;background:var(--line);margin:7px 0}.bar i{display:block;height:100%;background:var(--accent);border-radius:8px}\nhtml[data-theme=light] .green{color:#17683b;background:#e4f5ec}html[data-theme=light] .amber{color:#805100;background:#fff0d7}html[data-theme=light] .red{color:#a92b35;background:#ffe8eb}html[data-theme=light] .muted{color:#516778;background:#e9eef3}\n#global-notice{padding:12px 16px;border:1px solid var(--line);border-radius:10px;margin-top:16px;color:var(--ink);white-space:pre-wrap}#global-notice.bad{border-color:#b94655}\ndetails summary{cursor:pointer;color:var(--muted)}.top-tools{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.empty{text-align:center}#freshness{max-width:320px}\n@media(max-width:700px){.stats{grid-template-columns:repeat(2,1fr)}.top-tools{margin-top:16px}.control>*{flex:1}.control input,.control select{width:100%}}\n</style></head><body><main class=\"shell\"><header class=\"top\"><div><div class=\"eyebrow\">SH01 / system observability</div><h1 class=\"title\">Operations desk<span style=\"color:#81d5b7\">.</span></h1><p>Workflow failures, server exceptions and producer inventory in one place.</p><div class=\"meta\">Historical records begin when a source is connected. Stock reflects the latest sheet sync.</div></div><div class=\"top-tools\"><span class=\"meta\" id=\"session-age\"></span><button class=\"btn\" id=\"theme\">Light mode</button><div class=\"meta\" id=\"freshness\">No data loaded</div></div></header><section id=\"login\" class=\"card secret-panel\"><div class=\"eyebrow\">Private access</div><h2>Unlock dashboard</h2><p>Enter the dashboard token set in this Worker's secrets. Your unlock lasts 30 minutes in this tab, including reloads.</p><input id=\"token\" class=\"secret\" type=\"password\" autocomplete=\"off\" aria-label=\"Dashboard token\"><p><button class=\"btn\" id=\"unlock\">Open dashboard</button></p><div id=\"notice\" role=\"alert\"></div></section><section id=\"app\" class=\"hidden\"><div id=\"global-notice\" role=\"status\" aria-live=\"polite\" class=\"hidden\"></div><div class=\"nav\" role=\"tablist\"><button id=\"tab-failures\" role=\"tab\" aria-selected=\"true\">Failures</button><button id=\"tab-producers\" role=\"tab\" aria-selected=\"false\">Producers</button><button id=\"tab-meta\" role=\"tab\" aria-selected=\"false\">Meta analytics</button><button class=\"btn\" id=\"lock\" style=\"margin-left:auto\">Lock</button></div><div id=\"failure-view\" class=\"card\"><div class=\"eyebrow\">Event timeline</div><h2>Failures</h2><p class=\"legend\">Dates are UTC. No matching records does not prove the source is healthy. Coverage starts when each source is connected; messages are sanitized summaries.</p><div class=\"control\"><label>Search<input id=\"failure-search\" class=\"search\" placeholder=\"Workflow, error text, service\u2026\"></label><label>Source<select id=\"failure-source\"><option value=\"\">All sources</option><option value=\"n8n\">n8n</option><option value=\"sh01\">SH01 Python</option></select></label><label>From<input type=\"date\" id=\"from\"></label><label>To<input type=\"date\" id=\"to\"></label><button class=\"btn\" id=\"refresh-failures\">Refresh</button></div><div class=\"scroll\"><table><thead><tr><th>Time (UTC)</th><th>Source</th><th>Workflow / service</th><th>Error</th><th>Open</th></tr></thead><tbody id=\"failures\"></tbody></table></div><div id=\"failure-empty\" class=\"empty hidden\">No matching failures have been ingested.</div><button id=\"more\" class=\"btn hidden\" style=\"margin-top:16px\">Load more</button></div><div id=\"producer-view\" class=\"card hidden\"><div class=\"eyebrow\">Inventory / Google Sheets + workflow references</div><h2>Producers</h2><div id=\"sheet-health\" role=\"status\" class=\"legend\">Live source fetch not verified yet.</div><button class=\"btn\" id=\"sheet-sync-now\">Queue Sheets sync</button><div id=\"producer-stats\" class=\"stats\"></div><details><summary>How to read inventory status</summary><p class=\"legend\">Ready: available items exceed the warning threshold. Low: 1\u2013threshold items available. Consumed: every listed item is explicitly consumed. Unknown: no reliable stock count, no items, or items awaiting approval. Freshness is independent of stock status. A snapshot older than 30 minutes is labelled stale; this is a dashboard rule, not a workflow scheduling rule. Refresh reads stored D1 data. Run the collector to update it.</p></details><div class=\"control\" style=\"margin-top:18px\"><label>Search<input id=\"producer-search\" class=\"search\" placeholder=\"Producer, account or creator\u2026\"></label><label>Status<select id=\"producer-status\"><option value=\"\">All</option><option value=\"red\">Consumed</option><option value=\"amber\">Low inventory</option><option value=\"green\">Ready</option><option value=\"unknown\">Unknown</option></select></label><label>Freshness<select id=\"producer-fresh\"><option value=\"\">All snapshots</option><option value=\"stale\">Stale / unverified</option><option value=\"fresh\">Within 30 minutes</option></select></label><label>Sort<select id=\"producer-sort\"><option value=\"attention\">Needs attention</option><option value=\"name\">Producer name</option><option value=\"remaining\">Fewest available</option></select></label><button class=\"btn\" id=\"refresh-producers\">Refresh</button><button class=\"btn\" id=\"export-producers\">Export filtered CSV</button></div><div class=\"scroll\"><table><thead><tr><th>Producer</th><th>Available / total</th><th>Status</th><th>Workflow references</th><th>Source sync</th><th>Items</th></tr></thead><tbody id=\"producers\"></tbody></table></div><div id=\"producer-empty\" class=\"empty hidden\">No matching producers. Run the sheet sync to populate this view.</div><div id=\"item-panel\" class=\"hidden\"><button class=\"btn\" id=\"close-items\">Close items</button><h3 id=\"item-title\">Producer items</h3><p class=\"sub\">Links and values only; no media files are served here. Not ready does not necessarily mean consumed. At most 5,000 items are returned.</p><div class=\"scroll\"><table><thead><tr><th>Source row</th><th>Item link</th><th>Status</th><th>Approved</th><th>Availability</th></tr></thead><tbody id=\"items\"></tbody></table></div></div></div></section><section id=\"meta-view\" class=\"card hidden\"><div class=\"eyebrow\">Connected Meta assets</div><h2>Instagram &amp; Facebook analytics</h2><p>Metrics shown are retrieved from Meta. Missing permissions and unsupported metrics appear in Availability. Cumulative growth is observed between collections, not an event timeline.</p><button class=\"btn\" id=\"meta-sync\">Sync Meta now</button><span id=\"meta-notice\" class=\"sub\"></span><div class=\"nav\"><button class=\"btn\" id=\"meta-assets-tab\">Accounts</button><button class=\"btn\" id=\"meta-content-tab\">Content</button><button class=\"btn\" id=\"meta-cap-tab\">Availability</button></div><div id=\"meta-content-table\" class=\"scroll\"></div><div id=\"meta-chart\"></div></section></main><script>\n(()=>{'use strict';let token='',offset=0,controller=null,producerList=[];const SESSION_KEY='sh01-dashboard-session',SESSION_MS=30*60*1000;let sessionTimer;function clearSession(){clearTimeout(sessionTimer);sessionStorage.removeItem(SESSION_KEY)}function saveSession(){let expires=Date.now()+SESSION_MS;sessionStorage.setItem(SESSION_KEY,JSON.stringify({token,expires}));clearTimeout(sessionTimer);sessionTimer=setTimeout(lock,SESSION_MS)};const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));const href=v=>{try{let u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};const link=(v,label)=>{let h=href(v);return h?'<a href=\"'+esc(h)+'\" target=\"_blank\" rel=\"noopener noreferrer\">'+esc(label||v)+'</a>':'\u2014'};const wait=(fn,ms=260)=>{let t;return()=>{clearTimeout(t);t=setTimeout(fn,ms)}};async function api(path){let r=await fetch(path,{headers:{Authorization:'Bearer '+token},cache:'no-store'});if(r.status===401){lock();throw Error('Token rejected. Unlock again.')}if(!r.ok)throw Error('Request failed ('+r.status+')');return r.json()}function lock(){clearSession();token='';$('token').value='';$('app').classList.add('hidden');$('login').classList.remove('hidden');$('notice').textContent=''}function tab(which){for(let name of ['failures','producers','meta']){$('tab-'+name).setAttribute('aria-selected',name===which);$(name==='failures'?'failure-view':name==='producers'?'producer-view':'meta-view').classList.toggle('hidden',name!==which)}if(which==='producers')loadProducers().catch(showError);if(which==='meta')metaLoad('assets')}function showError(e){$('freshness').textContent=e.message||'Request failed'}function status(p){if(!p.sheet_backed)return 'unknown';if(!p.total_count)return 'unknown';if(!p.ready_count)return p.consumed_count===p.total_count?'red':'unknown';return p.ready_count<=p.threshold?'amber':'green'}function badge(s){return '<span class=\"badge '+s+'\">'+({green:'Ready',amber:'Low inventory',red:'Consumed',unknown:'Unknown'}[s])+'</span>'}async function loadFailures(reset=true){if(reset)offset=0;let q=new URLSearchParams({limit:'100',offset:String(offset)});for(let [key,id] of [['q','failure-search'],['source','failure-source'],['from','from'],['to','to']])if($(id).value.trim())q.set(key,$(id).value.trim());let d=await api('/api/failures?'+q);let rows=d.rows||[];if(reset)$('failures').innerHTML='';$('failures').insertAdjacentHTML('beforeend',rows.map(x=>'<tr><td>'+esc(x.happened_at)+'</td><td>'+esc(x.source)+'</td><td><strong>'+esc(x.workflow_name||x.service||'\u2014')+'</strong><div class=\"sub\">'+esc(x.service)+'</div></td><td class=\"error\">'+esc(x.message)+'</td><td>'+link(x.workflow_url,'Open \u2197')+'</td></tr>').join(''));offset+=rows.length;$('more').classList.toggle('hidden',rows.length<100);$('failure-empty').classList.toggle('hidden',offset>0);$('freshness').textContent='Last refreshed '+new Date().toLocaleString()}async function loadProducers(){let d=await api('/api/producers');producerList=d.rows||[];let health=d.sync||{};$('sheet-health').textContent='Google Sheets: '+(health.status||'never')+' \u00b7 last successful source fetch: '+(health.last_success||'never')+' UTC \u00b7 '+(health.stale?'STALE / UNVERIFIED':'within 30 minutes')+' \u00b7 scheduled every 10 minutes'+(health.error_code?' \u00b7 '+health.error_code:'')+(health.configured?'':' \u00b7 Google OAuth configuration incomplete');renderProducers();$('freshness').textContent='Last refreshed '+new Date().toLocaleString()}function renderProducers(){let q=$('producer-search').value.trim().toLowerCase(),desired=$('producer-status').value;let rows=producerList.filter(p=>(!q||(p.name+' '+p.account+' '+p.creator_handle+' '+p.workflow_names).toLowerCase().includes(q))&&(!desired||status(p)===desired));$('producer-stats').innerHTML=['Producers: '+producerList.length,'Low: '+producerList.filter(p=>status(p)==='amber').length,'Consumed: '+producerList.filter(p=>status(p)==='red').length].map(x=>'<span>'+esc(x)+'</span>').join('');$('producers').innerHTML=rows.map(p=>'<tr><td><strong>'+esc(p.name)+'</strong><div class=\"sub\">'+esc(p.account)+(p.creator_handle?' \u00b7 '+esc(p.creator_handle):'')+'</div></td><td>'+p.ready_count+' / '+p.total_count+'<div class=\"sub\">Warn at \u2264 '+p.threshold+'</div></td><td>'+badge(status(p))+'</td><td>'+esc(JSON.parse(p.workflow_names||'[]').join(', ')||'\u2014')+'</td><td><button class=\"btn item-button\" data-id=\"'+esc(p.producer_id)+'\">See items</button></td></tr>').join('');$('producer-empty').classList.toggle('hidden',rows.length>0)}async function showItems(id){let p=producerList.find(x=>x.producer_id===id);if(!p)return;let d=await api('/api/producers/'+encodeURIComponent(id)+'/items');$('item-title').textContent='Items \u00b7 '+p.name;$('items').innerHTML=d.rows.map(x=>'<tr><td>'+esc(x.origin)+' \u00b7 '+esc(x.item_id)+'</td><td>'+link(x.item_url,x.item_label||x.item_url)+'</td><td>'+esc(x.status)+'</td><td>'+esc(x.approved)+'</td><td>'+badge(x.ready?'green':'muted')+'</td></tr>').join('');$('item-panel').classList.remove('hidden');$('item-panel').scrollIntoView({behavior:'smooth',block:'nearest'})}$('unlock').onclick=async()=>{token=$('token').value.trim();if(!token)return;$('notice').textContent='Checking\u2026';try{await loadFailures();saveSession();$('login').classList.add('hidden');$('app').classList.remove('hidden');$('notice').textContent=''}catch(e){$('notice').textContent=e.message;token=''}};$('token').addEventListener('keydown',e=>{if(e.key==='Enter')$('unlock').click()});$('lock').onclick=lock;$('tab-failures').onclick=()=>tab('failures');$('tab-producers').onclick=()=>tab('producers');$('tab-meta').onclick=()=>tab('meta');$('refresh-failures').onclick=()=>loadFailures().catch(showError);$('refresh-producers').onclick=()=>loadProducers().catch(showError);$('more').onclick=()=>loadFailures(false).catch(showError);for(let id of ['failure-search','failure-source','from','to'])$(id).addEventListener('input',wait(()=>loadFailures().catch(showError)));for(let id of ['producer-search','producer-status'])$(id).addEventListener('input',renderProducers);\nasync function metaLoad(kind){let r=await api('/api/meta/'+kind);let rows=r.rows||[];let fields=kind==='assets'?['platform','name','id','page_id','updated_at']:kind==='content'?['platform','kind','published_at','caption','permalink','id']:['asset_id','kind','metric','status','reason','checked_at'];let table='<table><thead><tr>'+fields.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+fields.map(f=>'<td>'+(f==='permalink'?link(row[f],'Open post'):esc(row[f]??''))+'</td>').join('')+'</tr>').join('')+'</tbody></table>';$('meta-content-table').innerHTML=rows.length?table:'<p>No '+esc(kind)+' synced yet. Sync to discover accessible data.</p>';if(kind==='content'){$('meta-chart').innerHTML='<p class=\"sub\">Select a content ID and supported metric in the Availability tab to view its time series. Each timestamp records when Meta supplied the value.</p><input id=\"meta-id\" placeholder=\"Content ID\"><input id=\"meta-metric\" placeholder=\"Metric (e.g. views)\"><button class=\"btn\" id=\"meta-plot\">Plot snapshots</button><div id=\"meta-series\"></div>';$('meta-plot').onclick=async()=>{let id=$('meta-id').value.trim(),metric=$('meta-metric').value.trim();try{let d=await api('/api/meta/series?id='+encodeURIComponent(id)+'&metric='+encodeURIComponent(metric));let a=d.rows||[];$('meta-series').innerHTML=a.length?'<table><tr><th>Observed UTC</th><th>Value</th><th>Observed interval change</th></tr>'+a.map((x,i)=>'<tr><td>'+esc(x.observed_at)+'</td><td>'+esc(x.value)+'</td><td>'+esc(i&&x.value>=a[i-1].value?x.value-a[i-1].value:'\u2014')+'</td></tr>').join('')+'</table>':'No snapshots yet' }catch(e){$('meta-series').textContent=e.message}}}else $('meta-chart').innerHTML=''}\n$('meta-assets-tab').onclick=()=>metaLoad('assets').catch(showError);$('meta-content-tab').onclick=()=>metaLoad('content').catch(showError);$('meta-cap-tab').onclick=()=>metaLoad('capabilities').catch(showError);$('meta-sync').onclick=async()=>{$('meta-notice').textContent='Syncing\u2026';try{let d=await fetch('/api/meta/sync',{method:'POST',headers:{Authorization:'Bearer '+token}});if(!d.ok)throw Error('Sync incomplete; inspect Availability and Worker logs');$('meta-notice').textContent='Sync completed';metaLoad('assets')}catch(e){$('meta-notice').textContent=e.message}};\nlet sessionExpires=0,authEpoch=0,filteredProducers=[];\nconst inflight=new Map();\nconst tagList=values=>'<div class=\"tags\">'+values.filter(Boolean).map(v=>'<span class=\"tag\">'+esc(v)+'</span>').join('')+'</div>';\nconst sourceDate=v=>{if(!v)return null;let s=String(v);if(/^\\d{4}-\\d\\d-\\d\\d \\d\\d:/.test(s))s=s.replace(' ','T')+'Z';let d=new Date(s);return Number.isFinite(+d)?d:null};\nconst isStale=p=>p.source_stale!==undefined?p.source_stale:!sourceDate(p.updated_at)||Date.now()-sourceDate(p.updated_at)>1800000;\nconst workflowRefs=p=>{try{let x=JSON.parse(p.workflow_names||'[]');return Array.isArray(x)?x:[]}catch{return []}};\nfunction banner(message='',bad=false){$('global-notice').textContent=message;$('global-notice').classList.toggle('hidden',!message);$('global-notice').classList.toggle('bad',bad)}\nshowError=function(e){if(e.name!=='AbortError'){banner(e.message||'Request failed',true);$('freshness').textContent='Last request failed \u00b7 stored data may be stale'}};\nconst oldLock=lock;\nlock=function(){authEpoch++;for(let c of inflight.values())c.abort();inflight.clear();sessionExpires=0;oldLock();producerList=[];filteredProducers=[];offset=0;for(let id of ['producers','failures','items','producer-stats','meta-content-table','meta-chart'])$(id).replaceChildren();$('meta-view').classList.add('hidden');$('item-panel').classList.add('hidden');$('session-age').textContent='';$('freshness').textContent='Locked';banner()};\n$('lock').onclick=()=>lock();\nsaveSession=function(){sessionExpires=Date.now()+SESSION_MS;try{sessionStorage.setItem(SESSION_KEY,JSON.stringify({token,expires:sessionExpires}))}catch{banner('Session storage unavailable; reload will require signing in.')}clearTimeout(sessionTimer);sessionTimer=setTimeout(lock,SESSION_MS)};\ntry{let saved=JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null');if(saved&&saved.expires>Date.now())sessionExpires=Math.min(saved.expires,Date.now()+SESSION_MS)}catch{}\napi=async function(path){if(sessionExpires&&Date.now()>=sessionExpires){lock();throw Error('Session expired. Unlock again.')}let k=path.split('?')[0],epoch=authEpoch,c=new AbortController();inflight.get(k)?.abort();inflight.set(k,c);let timeout=setTimeout(()=>c.abort(),25000);try{let r=await fetch(path,{headers:{Authorization:'Bearer '+token},cache:'no-store',signal:c.signal});if(epoch!==authEpoch||inflight.get(k)!==c)throw new DOMException('Superseded','AbortError');if(r.status===401){lock();throw Error('Access rejected. Unlock again.')}if(!r.ok)throw Error('Request failed (HTTP '+r.status+'). Check source configuration and data coverage.');let d=await r.json();if(epoch!==authEpoch||inflight.get(k)!==c)throw new DOMException('Superseded','AbortError');return d}finally{clearTimeout(timeout);if(inflight.get(k)===c)inflight.delete(k)}};\nbadge=function(s){return '<span class=\"badge '+s+'\">'+({green:'Ready',amber:'Low inventory',red:'Consumed',unknown:'Unknown',muted:'Not ready'}[s]||'Unknown')+'</span>'};\n$('sheet-sync-now').onclick=async()=>{let b=$('sheet-sync-now');b.disabled=true;try{let r=await fetch('/api/sheets/sync',{method:'POST',headers:{Authorization:'Bearer '+token}});if(!r.ok)throw Error('Could not queue sync (HTTP '+r.status+')');$('sheet-health').textContent='Sheets sync queued. The next status refresh will show the result.'}catch(e){showError(e)}finally{b.disabled=false}};\nsetInterval(()=>{if(token&&!document.hidden&&!$('producer-view').classList.contains('hidden'))loadProducers().catch(showError)},60000);\nconst oldLoadProducers=loadProducers;\nloadProducers=async function(){banner('Loading stored inventory\u2026');await oldLoadProducers();banner(producerList.length>=2000?'Inventory reached the 2,000-producer API limit; more producers may exist.':'')};\nrenderProducers=function(){\n let terms=$('producer-search').value.trim().toLowerCase().split(/\\s+/),desired=$('producer-status').value,fresh=$('producer-fresh').value;\n let rows=producerList.filter(p=>terms.every(t=>(p.name+' '+p.account+' '+p.creator_handle+' '+workflowRefs(p).join(' ')).toLowerCase().includes(t))&&(!desired||status(p)===desired)&&(!fresh||(fresh==='stale')===isStale(p)));\n let order=$('producer-sort').value,rank={red:0,amber:1,unknown:2,green:3};\n rows.sort((a,b)=>order==='name'?String(a.name).localeCompare(b.name):order==='remaining'?a.ready_count-b.ready_count:rank[status(a)]-rank[status(b)]||String(a.name).localeCompare(b.name));filteredProducers=rows;\n $('producer-stats').innerHTML=[['Producers',producerList.length],['Low inventory',producerList.filter(p=>status(p)==='amber').length],['Consumed',producerList.filter(p=>status(p)==='red').length],['Stale / unverified',producerList.filter(isStale).length]].map(([label,n])=>'<span>'+esc(label)+'<strong>'+n+'</strong></span>').join('');\n $('producers').innerHTML=rows.map(p=>'<tr><td><strong>'+esc(p.name)+'</strong>'+tagList([p.account,p.creator_handle,p.source_kind|| (p.sheet_backed?'Sheet-backed':'Reference only')])+'</td><td><strong>'+p.ready_count+' available</strong><div class=\"sub\">'+p.total_count+' total \u00b7 '+p.consumed_count+' consumed</div><div class=\"bar\"><i style=\"width:'+Math.max(0,Math.min(100,p.total_count?100*p.ready_count/p.total_count:0))+'%\"></i></div><div class=\"sub\">Warn at \u2264 '+esc(p.threshold)+'</div></td><td>'+badge(status(p))+'</td><td>'+tagList(workflowRefs(p))+(workflowRefs(p).length?'':'<span class=\"sub\">No mapped references</span>')+'</td><td>'+(sourceDate(p.updated_at)?esc(sourceDate(p.updated_at).toLocaleString()):'Unknown')+'<div class=\"tags\"><span class=\"badge '+(isStale(p)?'amber':'green')+'\">'+(isStale(p)?'Stale / unknown':'Within 30 minutes')+'</span></div></td><td><button class=\"btn item-button\" data-id=\"'+esc(p.producer_id)+'\">See items</button></td></tr>').join('');\n $('producer-empty').classList.toggle('hidden',rows.length>0);\n};\nfor(let id of ['producer-fresh','producer-sort'])$(id).onchange=renderProducers;\n$('close-items').onclick=()=>{$('item-panel').classList.add('hidden');for(let [k,c] of inflight)if(k.endsWith('/items'))c.abort()};\n$('export-producers').onclick=()=>{const cols=['producer_id','name','account','creator_handle','ready_count','total_count','consumed_count','threshold','updated_at'];const cell=v=>{let s=String(v??'');if(/^\\s*[=+@-]/.test(s)||/^[\\t\\r\\n]/.test(s))s=\"'\"+s;return '\"'+s.replaceAll('\"','\"\"')+'\"'};let text=[cols.join(','),...filteredProducers.map(p=>cols.map(k=>cell(p[k])).join(','))].join('\\r\\n');let u=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='sh01-producer-inventory.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};\n$('theme').onclick=()=>{let light=document.documentElement.dataset.theme!=='light';document.documentElement.dataset.theme=light?'light':'dark';$('theme').textContent=light?'Dark mode':'Light mode';try{localStorage.setItem('sh01-theme',light?'light':'dark')}catch{}};\ntry{if(localStorage.getItem('sh01-theme')==='light')$('theme').click()}catch{}\nsetInterval(()=>{if(token&&sessionExpires){if(Date.now()>=sessionExpires)lock();else $('session-age').textContent='Session \u00b7 '+Math.ceil((sessionExpires-Date.now())/60000)+' min'}},1000);\ndocument.addEventListener('visibilitychange',()=>{if(token&&sessionExpires&&Date.now()>=sessionExpires)lock()});\nconst oldLoadFailures=loadFailures;\nloadFailures=async function(reset=true){if($('from').value&&$('to').value&&$('from').value>$('to').value)throw Error('From date must be on or before To date.');return oldLoadFailures(reset)};\n$('unlock').onclick=async()=>{if($('unlock').disabled)return;$('unlock').disabled=true;token=$('token').value.trim();if(!token){$('unlock').disabled=false;return}$('notice').textContent='Checking\u2026';try{await loadFailures();saveSession();$('token').value='';$('login').classList.add('hidden');$('app').classList.remove('hidden');$('notice').textContent=''}catch(e){$('notice').textContent=e.name==='AbortError'?'Request interrupted. Retry.':e.message;token=''}finally{$('unlock').disabled=false}};\nfunction guarded(button,fn){$(button).onclick=async()=>{let b=$(button);if(b.disabled)return;b.disabled=true;try{await fn()}catch(e){showError(e)}finally{b.disabled=false}}}\nguarded('refresh-producers',loadProducers);guarded('refresh-failures',()=>loadFailures());guarded('more',()=>loadFailures(false));\n\n$('producers').addEventListener('click',e=>{let b=e.target.closest('.item-button');if(b)showItems(b.dataset.id).catch(showError)});try{let saved=JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null');if(saved?.token&&saved.expires>Date.now()){token=saved.token;sessionTimer=setTimeout(lock,saved.expires-Date.now());loadFailures().then(()=>{$('login').classList.add('hidden');$('app').classList.remove('hidden')}).catch(()=>{lock();$('notice').textContent='Session expired or access rejected'})}else clearSession()}catch{clearSession()}})();\n</script></body></html>\n";

const json = (data, status = 200) => new Response(JSON.stringify(data), {status, headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const error = (message,status) => json({error:message},status);
async function authorized(given,expected){if(!given||!expected)return false;const e=new TextEncoder(),a=await crypto.subtle.digest('SHA-256',e.encode(given)),b=await crypto.subtle.digest('SHA-256',e.encode(expected));return Array.from(new Uint8Array(a)).every((x,i)=>x===new Uint8Array(b)[i]);}
function clean(s,max=500){return String(s??'').slice(0,max).replace(/(?:Bearer\s+|api[_-]?key\s*[=:]\s*|password\s*[=:]\s*)\S+/gi,'[REDACTED]').replace(/eyJ[A-Za-z0-9_-]{18,}\.eyJ[A-Za-z0-9_-]{18,}\.[A-Za-z0-9_-]{12,}/g,'[REDACTED]');}
function url(s){try{const u=new URL(String(s));if(!['http:','https:'].includes(u.protocol)||u.username||u.password)return '';u.hash='';for(const key of Array.from(u.searchParams.keys()))if(/token|secret|password|auth|signature|api.?key|credential/i.test(key))u.searchParams.set(key,'[REDACTED]');return u.href}catch{return ''}}
function iso(s){const d=new Date(s);return Number.isNaN(d.valueOf())?null:d.toISOString()}
function like(q){return `%${q.toLowerCase().replace(/[\\%_]/g,'\\$&')}%`}
async function body(req){if(Number(req.headers.get('Content-Length')||0)>900000)throw Error('Body too large');const t=await req.text();if(t.length>900000)throw Error('Body too large');return JSON.parse(t)}
async function ingestEvent(req,env){const b=await body(req);const events=Array.isArray(b.events)?b.events:[b];if(events.length>100)return error('Maximum 100 events',400);const statements=[];for(const x of events){if(!x||!['n8n','sh01'].includes(x.source)||!x.event_id||!iso(x.happened_at))return error('Invalid event',400);statements.push(env.DB.prepare(`INSERT INTO failures(source,event_id,happened_at,workflow_name,workflow_url,severity,message,service) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(source,event_id) DO UPDATE SET happened_at=excluded.happened_at,workflow_name=excluded.workflow_name,workflow_url=excluded.workflow_url,severity=excluded.severity,message=excluded.message,service=excluded.service`).bind(x.source,clean(x.event_id,150),iso(x.happened_at),clean(x.workflow_name,150),url(x.workflow_url),clean(x.severity,20),clean(x.message,700),clean(x.service,100)))}if(statements.length)await env.DB.batch(statements);return json({ok:true,accepted:statements.length})}
async function ingestProducer(req,env){const x=await body(req);if(!x||!x.producer_id||!x.name||!Array.isArray(x.items)||x.items.length>350)return error('Invalid producer batch; maximum 350 items',400);const id=clean(x.producer_id,180),threshold=Math.max(0,Math.min(100000,Number(x.threshold)||0)),workflows=JSON.stringify((x.workflow_names||[]).filter(v=>typeof v==='string').slice(0,100).map(v=>clean(v,120)));const statements=[env.DB.prepare(`INSERT INTO producers(producer_id,name,account,creator_handle,threshold,sheet_backed,workflow_names,updated_at) VALUES(?,?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(producer_id) DO UPDATE SET name=excluded.name,account=excluded.account,creator_handle=excluded.creator_handle,threshold=excluded.threshold,sheet_backed=excluded.sheet_backed,workflow_names=excluded.workflow_names,updated_at=CURRENT_TIMESTAMP`).bind(id,clean(x.name,150),clean(x.account,150),clean(x.creator_handle,150),threshold,x.sheet_backed?1:0,workflows)];if(x.reset)statements.push(env.DB.prepare('DELETE FROM producer_items WHERE producer_id=?').bind(id));for(const item of x.items){if(!item.item_id)return error('Missing item ID',400);statements.push(env.DB.prepare(`INSERT INTO producer_items(producer_id,item_id,item_label,item_url,status,approved,ready,origin) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(producer_id,item_id) DO UPDATE SET item_label=excluded.item_label,item_url=excluded.item_url,status=excluded.status,approved=excluded.approved,ready=excluded.ready,origin=excluded.origin`).bind(id,clean(item.item_id,150),clean(item.item_label,150),url(item.item_url),clean(item.status,60),clean(item.approved,60),item.ready?1:0,clean(item.origin,100)))}await env.DB.batch(statements);return json({ok:true,items:x.items.length})}
async function listFailures(req,env){const u=new URL(req.url),q=(u.searchParams.get('q')||'').trim().split(/\s+/).filter(Boolean).slice(0,5),where=[],args=[];let source=u.searchParams.get('source');if(source){if(!['n8n','sh01'].includes(source))return error('Invalid source',400);where.push('source=?');args.push(source)}for(const [k,op] of [['from','>='],['to','<']]){let v=u.searchParams.get(k);if(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return error('Invalid date',400);const d=k==='to'?new Date(Date.parse(v+'T00:00:00Z')+86400000).toISOString():v+'T00:00:00.000Z';where.push(`happened_at ${op} ?`);args.push(d)}}for(let term of q){where.push(`(lower(workflow_name) LIKE ? ESCAPE '\\' OR lower(message) LIKE ? ESCAPE '\\' OR lower(service) LIKE ? ESCAPE '\\')`);args.push(like(term),like(term),like(term))}const limit=Math.min(100,Math.max(1,Number(u.searchParams.get('limit'))||100)),offset=Math.min(100000,Math.max(0,Number(u.searchParams.get('offset'))||0));const sql='SELECT source,event_id,happened_at,workflow_name,workflow_url,severity,message,service FROM failures'+(where.length?' WHERE '+where.join(' AND '):'')+' ORDER BY happened_at DESC LIMIT ? OFFSET ?';const {results}=await env.DB.prepare(sql).bind(...args,limit,offset).all();return json({rows:results})}
async function listProducers(env){const {results}=await env.DB.prepare(`SELECT p.*,COUNT(i.item_id) total_count,COALESCE(SUM(i.ready),0) ready_count,COALESCE(SUM(CASE WHEN lower(i.status) IN ('used','published','consumed','done','posted','completed','deleted') THEN 1 ELSE 0 END),0) consumed_count FROM producers p LEFT JOIN producer_items i ON i.producer_id=p.producer_id GROUP BY p.producer_id ORDER BY lower(p.name) LIMIT 2000`).all();return json({rows:results})}
// Meta analytics extension for the dashboard. Bundled into worker.js by build_single_worker.py.
// META_SYSVAR may be a token or JSON containing access_token/token. Never persist either.
const META_VERSION='v24.0';
const IG_METRICS={IMAGE:['views','reach','likes','comments','saved','shares','total_interactions'],VIDEO:['views','reach','likes','comments','saved','shares','total_interactions'],CAROUSEL_ALBUM:['views','reach','likes','comments','saved','shares','total_interactions'],REELS:['views','reach','likes','comments','saved','shares','total_interactions','ig_reels_avg_watch_time','ig_reels_video_view_total_time','clips_replays_count','reels_skip_rate'],STORY:['views','reach','replies','shares','navigation','taps_forward','taps_back','exits','follows','profile_visits']};
const IG_ACCOUNT_METRICS=['reach','views','accounts_engaged','total_interactions','follower_count','profile_views','website_clicks'];
const PAGE_METRICS=['page_impressions','page_post_engagements','page_fans','page_fan_adds','page_views_total'];
function metaCredential(raw){if(!raw||typeof raw!=='string')throw Error('META_SYSVAR missing');let v=raw.trim();if(v.startsWith('{')){let obj;try{obj=JSON.parse(v)}catch{throw Error('META_SYSVAR structure invalid')}v=obj.access_token||obj.token||obj.page_access_token||obj.user_access_token;if(typeof v!=='string')throw Error('META_SYSVAR has no supported access token field')}if(!/^[A-Za-z0-9._-]{20,}$/.test(v))throw Error('META_SYSVAR credential format unsupported');return v}
async function graph(path,token,params={}){let u=new URL('https://graph.facebook.com/'+META_VERSION+'/'+path.replace(/^\//,''));for(let [k,v] of Object.entries(params))u.searchParams.set(k,String(v));let attempts=0;while(true){let res;try{res=await fetch(u.toString(),{headers:{Authorization:'Bearer '+token},signal:AbortSignal.timeout(15000)})}catch{throw Error('network_unavailable')}if(res.status===429||res.status>=500){if(attempts++<2){await new Promise(r=>setTimeout(r,400*2**attempts));continue}throw Error('rate_limited_or_unavailable')}let obj;try{obj=await res.json()}catch{throw Error('invalid_graph_response')}if(!res.ok||obj.error){let code=obj?.error?.code||res.status;throw Error('Graph error '+String(code).slice(0,8))}return obj}}
async function graphPages(path,token,params,max=10){let all=[],cursor;for(let i=0;i<max;i++){let data=await graph(path,token,{...params,...(cursor?{after:cursor}:{})});if(!Array.isArray(data.data))throw Error('unexpected_pagination');all.push(...data.data);let next=data.paging?.cursors?.after;if(!next||next===cursor||!data.paging?.next)break;cursor=next}return all}
async function metaIssue(db,asset,kind,metric,reason){await db.prepare('INSERT INTO meta_capabilities(asset_id,kind,metric,status,reason,checked_at) VALUES(?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(asset_id,kind,metric) DO UPDATE SET status=excluded.status,reason=excluded.reason,checked_at=CURRENT_TIMESTAMP').bind(asset,kind,metric,'unavailable',reason.slice(0,100)).run()}
function safeMetricValues(raw){let values=[];for(let v of raw?.values||[])if(typeof v.value==='number'&&Number.isFinite(v.value))values.push({at:v.end_time||null,value:v.value});return values}
async function metricProbe(db,id,kind,metric,token,params={}){try{let data=await graph(id+'/insights',token,{metric,...params});let series=(data.data||[]).filter(x=>x.name===metric).flatMap(x=>safeMetricValues(x));await db.prepare('INSERT INTO meta_capabilities(asset_id,kind,metric,status,reason,checked_at) VALUES(?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(asset_id,kind,metric) DO UPDATE SET status=excluded.status,reason=excluded.reason,checked_at=CURRENT_TIMESTAMP').bind(id,kind,metric,'available','').run();for(let item of series){let at=item.at||new Date().toISOString();await db.prepare('INSERT INTO meta_snapshots(asset_id,kind,metric,observed_at,value,source_period) VALUES(?,?,?,?,?,?) ON CONFLICT(asset_id,kind,metric,observed_at) DO UPDATE SET value=excluded.value').bind(id,kind,metric,at,item.value,params.period||'lifetime').run()}return series.length}catch(e){await metaIssue(db,id,kind,metric,e.message);return 0}}
async function metaSync(env){let db=env.DB,token=metaCredential(env.META_SYSVAR),started=new Date().toISOString(),stats={pages:0,ig_accounts:0,media:0,snapshots:0};let pages=await graphPages('me/accounts',token,{fields:'id,name,instagram_business_account,access_token',limit:100},20);for(let page of pages){if(!page.id)continue;let pt=page.access_token||token;await db.prepare('INSERT INTO meta_assets(id,platform,name,page_id,updated_at) VALUES(?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(id) DO UPDATE SET name=excluded.name,updated_at=CURRENT_TIMESTAMP').bind(page.id,'facebook',page.name||'',null).run();stats.pages++;for(let m of PAGE_METRICS)stats.snapshots+=await metricProbe(db,page.id,'page',m,pt,{period:'day'});let ig=page.instagram_business_account?.id;if(!ig)continue;let profile;try{profile=await graph(ig,pt,{fields:'id,username,name,followers_count,media_count,profile_picture_url'})}catch(e){await metaIssue(db,ig,'account','profile',e.message);continue}await db.prepare('INSERT INTO meta_assets(id,platform,name,page_id,updated_at) VALUES(?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(id) DO UPDATE SET name=excluded.name,page_id=excluded.page_id,updated_at=CURRENT_TIMESTAMP').bind(ig,'instagram',profile.username||profile.name||'',page.id).run();stats.ig_accounts++;for(let m of IG_ACCOUNT_METRICS)stats.snapshots+=await metricProbe(db,ig,'account',m,pt,{period:'day'});let feed=[];try{feed=await graphPages(ig+'/media',pt,{fields:'id,media_type,media_product_type,timestamp,caption,permalink,thumbnail_url,media_url,like_count,comments_count',limit:100},10)}catch(e){await metaIssue(db,ig,'media','list',e.message)}let stories=[];try{stories=await graphPages(ig+'/stories',pt,{fields:'id,media_type,timestamp,permalink,thumbnail_url',limit:100},3)}catch(e){await metaIssue(db,ig,'stories','list',e.message)}for(let item of [...feed,...stories]){let kind=stories.includes(item)?'STORY':item.media_product_type==='REELS'?'REELS':item.media_type||'IMAGE';await db.prepare('INSERT INTO meta_content(id,asset_id,platform,kind,published_at,caption,permalink,thumbnail_url,first_seen,last_seen) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET last_seen=excluded.last_seen,caption=excluded.caption,thumbnail_url=excluded.thumbnail_url').bind(item.id,ig,'instagram',kind,item.timestamp||'',String(item.caption||'').slice(0,1200),item.permalink||'',item.thumbnail_url||'',started,started).run();stats.media++;for(let m of IG_METRICS[kind]||[])stats.snapshots+=await metricProbe(db,item.id,kind,m,pt)} }return stats}
async function metaApi(req,env){let p=new URL(req.url).pathname;if(p==='/api/meta/sync'&&req.method==='POST'){if(!env.META_SYSVAR)return json({error:'META_SYSVAR missing'},503);try{return json({ok:true,result:await metaSync(env)})}catch(e){return json({error:e.message==='META_SYSVAR missing'?e.message:'Meta sync failed; see capability inventory'},503)}}if(req.method!=='GET')return error('Not found',404);let sql=p==='/api/meta/assets'?'SELECT * FROM meta_assets ORDER BY platform,name':p==='/api/meta/content'?'SELECT * FROM meta_content ORDER BY published_at DESC LIMIT 1000':p==='/api/meta/capabilities'?'SELECT * FROM meta_capabilities ORDER BY asset_id,kind,metric':null;if(sql)return json({rows:(await env.DB.prepare(sql).all()).results});if(p==='/api/meta/series'){let u=new URL(req.url),id=u.searchParams.get('id'),metric=u.searchParams.get('metric');if(!/^\d{5,30}$/.test(id||'')||!/^[a-z_]{2,70}$/.test(metric||''))return error('Invalid selection',400);return json({rows:(await env.DB.prepare('SELECT observed_at,value,source_period FROM meta_snapshots WHERE asset_id=? AND metric=? ORDER BY observed_at LIMIT 5000').bind(id,metric).all()).results})}return error('Not found',404)}

// Automatic read-only Google Sheets collector. Tokens never enter D1.
const SHEET_TABS=['streamables','streamables-yt','workflow-schedule'];
async function sheetJSON(url,options={}){
 for(let attempt=0;attempt<3;attempt++){
  let r;try{r=await fetch(url,{...options,signal:AbortSignal.timeout(20000)})}catch{if(attempt<2)continue;throw Error('google_network_timeout')}
  if((r.status===429||r.status>=500)&&attempt<2){await new Promise(ok=>setTimeout(ok,500*2**attempt));continue}
  if(!r.ok)throw Error('google_http_'+r.status);
  try{return await r.json()}catch{throw Error('google_invalid_json')}
 }
}
async function sheetToken(env){
 for(let k of ['GOOGLE_CLIENT_ID','GOOGLE_CLIENT_SECRET','GOOGLE_REFRESH_TOKEN','GOOGLE_SHEETS_SPREADSHEET_ID'])if(!env[k])throw Error('missing_'+k);
 const data=await sheetJSON('https://oauth2.googleapis.com/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:env.GOOGLE_CLIENT_ID,client_secret:env.GOOGLE_CLIENT_SECRET,refresh_token:env.GOOGLE_REFRESH_TOKEN,grant_type:'refresh_token'})});
 if(typeof data.access_token!=='string')throw Error('google_refresh_failed');return data.access_token;
}
async function readSheet(env,token,title){
 const range="'"+title.replaceAll("'","''")+"'!A:Z";
 const u='https://sheets.googleapis.com/v4/spreadsheets/'+encodeURIComponent(env.GOOGLE_SHEETS_SPREADSHEET_ID)+'/values/'+encodeURIComponent(range);
 const data=await sheetJSON(u,{headers:{Authorization:'Bearer '+token}});
 const rows=data.values||[];
 if(!Array.isArray(rows))throw Error('sheet_invalid_shape');
 if(rows.length>20000)throw Error('sheet_row_limit_reached');
 return rows;
}
const sheetText=x=>String(x??'').trim();
function sheetRows(rows,title){
 if(!rows.length)throw Error('sheet_missing_header');
 let headers=rows[0].map(x=>sheetText(x).toLowerCase());
 const required=title==='workflow-schedule'?['associated accounts']:['account','creator_handle','status','approved'];
 if(required.some(x=>!headers.includes(x)))throw Error('sheet_required_columns_missing');
 return rows.slice(1).map((cells,i)=>({row:i+2,data:Object.fromEntries(headers.map((h,n)=>[h,cells[n]??'']))}));
}
async function producerHash(s){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))),x=>x.toString(16).padStart(2,'0')).join('').slice(0,32)}
async function sheetSync(env){
 const db=env.DB,lease=crypto.randomUUID(),started=new Date().toISOString();
 await db.prepare("INSERT OR IGNORE INTO sheet_sync_state(id,status) VALUES(1,'never')").run();
 let acquired=await db.prepare("UPDATE sheet_sync_state SET lease=?,lease_until=?,last_attempt=?,status='running' WHERE id=1 AND (lease_until IS NULL OR lease_until<?)").bind(lease,Date.now()+300000,started,Date.now()).run();
 if(!acquired.meta.changes)return {status:'already_running'};
 const version=crypto.randomUUID();
 try{
  let token=await sheetToken(env),tables=[];
  for(let title of SHEET_TABS)tables.push([title,sheetRows(await readSheet(env,token,title),title)]);
  const existing=(await db.prepare('SELECT producer_id,threshold,workflow_names FROM producers').all()).results;
  const old=new Map(existing.map(p=>[p.producer_id,p])),groups=new Map(),schedule=new Set();
  for(let [title,rows] of tables)for(let {row,data:r} of rows){
   if(!Object.values(r).some(x=>sheetText(x)))continue;
   if(title==='workflow-schedule'){for(let a of sheetText(r['associated accounts']).split(','))if(a.trim())schedule.add(a.trim());continue}
   let account=sheetText(r.account),creator=sheetText(r.creator_handle);if(!account&&!creator)account='Unattributed / '+title;
   let id=await producerHash(account.toLowerCase()+'\0'+creator.toLowerCase()),g=groups.get(id);
   if(!g){g={producer_id:id,name:account||creator,account,creator_handle:creator,threshold:old.get(id)?.threshold??3,workflow_names:old.get(id)?.workflow_names||'[]',sheet_backed:1,items:[]};groups.set(id,g)}
   let status=sheetText(r.status),approved=sheetText(r.approved);
   g.items.push({item_id:title+':'+row,item_label:clean(sheetText(r.caption).slice(0,140)||'Row '+row,140),item_url:url(sheetText(r.yt_link)||sheetText(r['public drive link'])),status:clean(status,60),approved:clean(approved,60),ready:['yes','true','approved','1','y'].includes(approved.toLowerCase())&&!['used','published','consumed','done','posted','completed','deleted'].includes(status.toLowerCase())?1:0,origin:title});
  }
  let names=new Set([...groups.values()].map(g=>g.name.toLowerCase()));
  for(let name of schedule)if(!names.has(name.toLowerCase())){
   let id=await producerHash('schedule\0'+name.toLowerCase());groups.set(id,{producer_id:id,name,account:name,creator_handle:'',threshold:old.get(id)?.threshold??3,workflow_names:old.get(id)?.workflow_names||'[]',sheet_backed:0,items:[]});
  }
  let fetched=new Date().toISOString(),batch=[];
  const flush=async()=>{if(batch.length){await db.batch(batch);batch=[]}};
  for(let g of groups.values()){
   batch.push(db.prepare('INSERT INTO sheet_live_producers(version,producer_id,payload,fetched_at) VALUES(?,?,?,?)').bind(version,g.producer_id,JSON.stringify({...g,items:undefined,name:clean(g.name,150),account:clean(g.account,150),creator_handle:clean(g.creator_handle,150),total_count:g.items.length,ready_count:g.items.reduce((n,i)=>n+i.ready,0),consumed_count:g.items.filter(i=>['used','published','consumed','done','posted','completed','deleted'].includes(i.status.toLowerCase())).length}),fetched));
   for(let i of g.items){batch.push(db.prepare('INSERT INTO sheet_live_items(version,producer_id,item_id,payload) VALUES(?,?,?,?)').bind(version,g.producer_id,i.item_id,JSON.stringify(i)));if(batch.length>=80)await flush()}
   if(batch.length>=80)await flush();
  }
  await flush();
  let published=await db.prepare("UPDATE sheet_sync_state SET active_version=?,last_success=?,status='ok',error_code=NULL,lease=NULL,lease_until=NULL WHERE id=1 AND lease=? AND lease_until>?").bind(version,fetched,lease,Date.now()).run();
  if(!published.meta.changes)throw Error('sheet_lease_expired');
  // Old snapshots retained for an hour to avoid disrupting in-flight reads.
  await db.prepare("DELETE FROM sheet_live_items WHERE version IN (SELECT DISTINCT version FROM sheet_live_producers WHERE fetched_at<? AND version<>(SELECT active_version FROM sheet_sync_state WHERE id=1))").bind(new Date(Date.now()-3600000).toISOString()).run();
  await db.prepare("DELETE FROM sheet_live_producers WHERE fetched_at<? AND version<>(SELECT active_version FROM sheet_sync_state WHERE id=1)").bind(new Date(Date.now()-3600000).toISOString()).run();
  return {status:'ok',producers:groups.size,fetched_at:fetched};
 }catch(e){
  let code=/^(missing_GOOGLE_[A-Z_]+|google_http_\d+|google_network_timeout|google_invalid_json|google_refresh_failed|sheet_[a-z_]+)$/.test(e.message)?e.message:'sync_internal_error';
  await db.prepare("UPDATE sheet_sync_state SET status='failed',error_code=?,lease=NULL,lease_until=NULL WHERE id=1 AND lease=?").bind(code,lease).run();
  return {status:'failed',error_code:code}; // No upstream body or credential logging.
 }
}
async function sheetStatus(env){const s=await env.DB.prepare('SELECT status,last_attempt,last_success,error_code,active_version,lease_until FROM sheet_sync_state WHERE id=1').first();return {...s,configured:!!(env.GOOGLE_CLIENT_ID&&env.GOOGLE_CLIENT_SECRET&&env.GOOGLE_REFRESH_TOKEN&&env.GOOGLE_SHEETS_SPREADSHEET_ID),stale:!s?.last_success||Date.now()-Date.parse(s.last_success)>1800000,interval_minutes:10}}
async function liveProducerList(env){
 let state=await sheetStatus(env);
 let legacy=(await env.DB.prepare('SELECT p.*,COUNT(i.item_id) total_count,COALESCE(SUM(i.ready),0) ready_count,COALESCE(SUM(CASE WHEN lower(i.status) IN (\'used\',\'published\',\'consumed\',\'done\',\'posted\',\'completed\',\'deleted\') THEN 1 ELSE 0 END),0) consumed_count FROM producers p LEFT JOIN producer_items i ON i.producer_id=p.producer_id GROUP BY p.producer_id LIMIT 2000').all()).results;
 if(!state.active_version)return json({rows:legacy.map(p=>({...p,updated_at:null,source_kind:'archive_or_manual',source_stale:true})),sync:state});
 let rows=(await env.DB.prepare('SELECT payload,fetched_at FROM sheet_live_producers WHERE version=?').bind(state.active_version).all()).results.map(x=>({...JSON.parse(x.payload),updated_at:x.fetched_at,source_kind:'google_sheets_live',source_stale:state.stale}));
 let ids=new Set(rows.map(x=>x.producer_id));
 // Retain workflow-only archive references. Old stock/schedule rows are superseded.
 for(let p of legacy)if(!p.sheet_backed&&!ids.has(p.producer_id)&&!p.account)rows.push({...p,updated_at:null,source_kind:'archive_reference',source_stale:true});
 return json({rows,sync:state});
}
async function liveProducerItems(env,id){
 const state=await sheetStatus(env);
 if(state.active_version){
  let found=await env.DB.prepare('SELECT producer_id FROM sheet_live_producers WHERE version=? AND producer_id=?').bind(state.active_version,id).first();
  if(found){let r=await env.DB.prepare('SELECT payload FROM sheet_live_items WHERE version=? AND producer_id=? ORDER BY item_id LIMIT 5000').bind(state.active_version,id).all();return json({rows:r.results.map(x=>JSON.parse(x.payload))})}
 }
 return json({rows:(await env.DB.prepare('SELECT item_id,item_label,item_url,status,approved,ready,origin FROM producer_items WHERE producer_id=? LIMIT 5000').bind(id).all()).results});
}

export default {async scheduled(event,env,ctx){ctx.waitUntil(sheetSync(env).catch(()=>console.log('sheets_sync_setup_failure')))},async fetch(req,env,ctx){const u=new URL(req.url),p=u.pathname;if(p==='/'&&req.method==='GET')return new Response(HTML,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','Content-Security-Policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"}});if(!p.startsWith('/api/'))return error('Not found',404);if(!env.DB)return error('D1 binding DB missing',503);const ingest=p.startsWith('/api/ingest/');const given=ingest?req.headers.get('X-INGEST-KEY'):(req.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'');if(!await authorized(given,ingest?env.INGEST_TOKEN:env.DASHBOARD_TOKEN))return error('Unauthorized',401);try{if(p==='/api/sheets/status'&&req.method==='GET')return json(await sheetStatus(env));if(p==='/api/sheets/sync'&&req.method==='POST'){ctx.waitUntil(sheetSync(env).catch(()=>console.log('sheets_sync_setup_failure')));return json({status:'queued'},202);}if(p.startsWith('/api/meta/'))return await metaApi(req,env);if(ingest&&req.method==='POST'&&p==='/api/ingest/event')return await ingestEvent(req,env);if(ingest&&req.method==='POST'&&p==='/api/ingest/producer')return await ingestProducer(req,env);if(req.method==='GET'&&p==='/api/failures')return await listFailures(req,env);if(req.method==='GET'&&p==='/api/producers')return await liveProducerList(env);let m=p.match(/^\/api\/producers\/([^/]+)\/items$/);if(req.method==='GET'&&m){let id=decodeURIComponent(m[1]);return await liveProducerItems(env,id)}return error('Not found',404)}catch(e){return error('Request could not be completed',400)}}};

